style.css:
/* Midnight Google — Google */

:root {
  /* swap these colors if you want */
  --my-bg: #080808;
  --my-surface: #151515;
  --my-text: #eeeeee;
  --my-muted: #999999;
  --my-accent: #ff3030;
}

/* dark background */
html,
body {
  background: var(--my-bg) !important;
  color: var(--my-text) !important;
}

/* text */
h1, h2, h3, p, span, label {
  color: var(--my-text) !important;
}

/* search bar */
textarea,
input[type="text"],
input[type="search"] {
  background: var(--my-surface) !important;
  color: var(--my-text) !important;
  border: 1px solid #303030 !important;
  border-radius: 30px !important;
}

/* buttons */
button {
  background: var(--my-surface) !important;
  color: var(--my-text) !important;
  border: 1px solid #303030 !important;
  border-radius: 20px !important;
}

/* links */
a {
  color: var(--my-accent) !important;
}

/* images */
img {
  border-radius: 10px;
}
